 475	impl ReleaseDecisionV1 {
 476	    pub const SCHEMA_VERSION: u8 = 1;
 477	
 478	    /// Creates a canonical decision or rejects an ambiguous release roster.
 479	    #[allow(clippy::result_large_err)]
 480	    pub fn new(mut entries: Vec<ReleaseDecisionEntry>) -> Result<Self, ReleaseDecisionError> {
 481	        if entries.is_empty() {
 482	            return Err(ReleaseDecisionError::EmptyRoster);
 483	        }
 484	        for entry in &mut entries {
 485	            entry.reasons.sort();
 486	            entry.reasons.dedup();
 487	            if entry.reasons.is_empty() {
 488	                return Err(ReleaseDecisionError::MissingReason {
 489	                    package: entry.package.clone(),
 490	                });
 491	            }
 492	        }
 493	        entries.sort_by(|left, right| left.package.cmp(&right.package));
 494	        if entries.windows(2).any(|pair| pair[0].package == pair[1].package) {
 495	            return Err(ReleaseDecisionError::DuplicatePackage);
 496	        }
 497	
 498	        // A fixed or linked group always converges every member to one
 499	        // shared target version -- `solve_cascade` guarantees this when a
 500	        // decision is derived from a version plan. Entries tag their own
 501	        // group membership via `FixedGroup`/`LinkedGroup` reasons, so this
 502	        // invariant is checkable from the decision's own content alone, with
 503	        // no `GroupTable`/workspace-config access needed. Rejecting a
 504	        // violation here means it also applies to a decision deserialized
 505	        // from a committed release-decision file (`Deserialize` calls
 506	        // `new()`), not just one freshly derived from a plan.
 507	        let mut group_targets: BTreeMap<&str, &Version> = BTreeMap::new();
 508	        for entry in &entries {
 509	            for reason in &entry.reasons {
 510	                let group_id = match reason {
 511	                    ReleaseInclusionReason::FixedGroup { group_id }
 512	                    | ReleaseInclusionReason::LinkedGroup { group_id } => group_id.as_str(),
 513	                    _ => continue,
 514	                };
 515	                match group_targets.get(group_id) {
 516	                    Some(existing) if **existing != entry.target_version => {
 517	                        return Err(ReleaseDecisionError::DivergentGroupTarget {
 518	                            group_id: group_id.to_string(),
 519	                            left: (*existing).clone(),
 520	                            right: entry.target_version.clone(),
 521	                        });
 522	                    }
 523	                    _ => {
 524	                        group_targets.insert(group_id, &entry.target_version);
 525	                    }
 526	                }
 527	            }
 528	        }
 529	
 530	        let digest = decision_digest(&entries);
 531	        Ok(Self {
 532	            schema_version: Self::SCHEMA_VERSION,
 533	            entries,
 534	            digest,
 535	        })
 536	    }
 537	}
 538	
 539	fn decision_digest(entries: &[ReleaseDecisionEntry]) -> DecisionDigest {
 540	    let mut transcript = CanonicalTranscript::decision_v1();
 541	    for entry in entries {
 542	        transcript.push_str("package", &entry.package.to_string());
 543	        transcript.push_str("target-version", entry.target_version.render());
 544	        for reason in &entry.reasons {
 545	            transcript.push_str(
 546	                "reason",
 547	                &serde_json::to_string(reason).expect("closed reason serializes"),
 548	            );
 549	        }
 550	    }
 551	    DecisionDigest::from_transcript(&transcript)
 552	}
