 600	/// Deterministic length-prefixed bytes for a durable release digest.
 601	///
 602	/// The transcript starts with a fixed protocol marker, a one-byte schema
 603	/// version, and a length-prefixed domain. Each appended field is a
 604	/// length-prefixed UTF-8 tag followed by a length-prefixed byte value. Domain
 605	/// types own ordering of fields; this primitive preserves that order exactly.
 606	#[derive(Clone, Debug, PartialEq, Eq)]
 607	pub struct CanonicalTranscript {
 608	    bytes: Vec<u8>,
 609	}
 610	
 611	impl CanonicalTranscript {
 612	    const MARKER: &'static [u8] = b"callisto-release-transcript";
 613	    const VERSION: u8 = 1;
 614	
 615	    /// Starts the v1 transcript used for semantic input snapshots.
 616	    pub fn semantic_input_v1() -> Self {
 617	        Self::v1(b"semantic-input")
 618	    }
 619	
 620	    /// Starts the v1 transcript used for release decisions.
 621	    pub fn decision_v1() -> Self {
 622	        Self::v1(b"release-decision")
 623	    }
 624	
 625	    /// Starts the v1 transcript used for release intents.
 626	    pub fn intent_v1() -> Self {
 627	        Self::v1(b"release-intent")
 628	    }
 629	
 630	    /// Starts the v1 transcript used for normalized registry bindings.
 631	    fn registry_binding_v1() -> Self {
 632	        Self::v1(b"registry-binding")
 633	    }
 634	
 635	    fn v1(domain: &[u8]) -> Self {
 636	        let mut bytes = Vec::with_capacity(Self::MARKER.len() + domain.len() + 16);
 637	        Self::push_length_prefixed(&mut bytes, Self::MARKER);
 638	        bytes.push(Self::VERSION);
 639	        Self::push_length_prefixed(&mut bytes, domain);
 640	        Self { bytes }
 641	    }
 642	
 643	    /// Appends one named UTF-8 field.
 644	    pub fn push_str(&mut self, tag: &str, value: &str) {
 645	        self.push_bytes(tag, value.as_bytes());
 646	    }
 647	
 648	    /// Appends one named byte field.
 649	    pub fn push_bytes(&mut self, tag: &str, value: impl AsRef<[u8]>) {
 650	        Self::push_length_prefixed(&mut self.bytes, tag.as_bytes());
 651	        Self::push_length_prefixed(&mut self.bytes, value.as_ref());
 652	    }
 653	
 654	    /// Returns the exact canonical bytes, suitable only for hashing or test vectors.
 655	    pub fn as_bytes(&self) -> &[u8] {
 656	        &self.bytes
 657	    }
 658	
 659	    fn push_length_prefixed(out: &mut Vec<u8>, value: &[u8]) {
 660	        let length = u64::try_from(value.len()).expect("usize always fits in u64 on supported platforms");
 661	        out.extend_from_slice(&length.to_be_bytes());
 662	        out.extend_from_slice(value);
 663	    }
 664	}
