 957	// Hand-written rather than derived: `Version` has no `Ord` impl (SemVer and PEP 440
 958	// aren't comparable via a single total order), so this struct can't `#[derive(Ord)]`
 959	// directly. `role` delegates to `ReleaseOperationRole`'s own derived `Ord`, which
 960	// folds in every field of every variant -- including `ArtifactSlotId::attestation_policy`
 961	// for `ArtifactUpload` -- instead of hand-decomposing it into a lossy sort key.
 962	// `version` goes through `version_ord_key` (grammar + raw), not bare `render()`: two
 963	// `Version`s under different grammars can render identically (e.g. `"1.2.3"` is valid
 964	// both as SemVer and PEP 440), which a `render()`-only key would wrongly fold together.
 965	impl Ord for ReleaseOperationId {
 966	    fn cmp(&self, other: &Self) -> Ordering {
