2587	            return Err(SuccessorError::InvalidPrerequisite);
2588	        }
2589	        let mut upload_ids = operations
2590	            .iter()
2591	            .filter_map(|operation| {
2592	                matches!(operation.id, ReleaseOperationId::ArtifactUpload { .. }).then_some(operation.id.clone())
2593	            })
2594	            .collect::<Vec<_>>();
2595	        upload_ids.sort();
2596	        if publishes[0].prerequisites != upload_ids {
2597	            return Err(SuccessorError::InvalidPrerequisite);
2598	        }
2599	        let edges: BTreeMap<_, _> = operations
2600	            .iter()
2601	            .map(|operation| (operation.id.clone(), operation.prerequisites.clone()))
2602	            .collect();
2603	        let canonical = stable_order(&edges)?;
2604	        if operations.iter().map(|operation| &operation.id).ne(canonical.iter()) {
