2610	    fn stable_order(
2611	        prerequisites: &BTreeMap<ReleaseOperationId, Vec<ReleaseOperationId>>,
2612	    ) -> Result<Vec<ReleaseOperationId>, SuccessorError> {
2613	        let mut remaining: BTreeMap<_, _> = prerequisites
2614	            .iter()
2615	            .map(|(id, prerequisites)| (id.clone(), prerequisites.len()))
2616	            .collect();
2617	        let mut dependents = BTreeMap::<ReleaseOperationId, Vec<ReleaseOperationId>>::new();
2618	        for (id, prerequisites) in prerequisites {
2619	            for prerequisite in prerequisites {
2620	                dependents.entry(prerequisite.clone()).or_default().push(id.clone());
2621	            }
2622	        }
2623	        let mut ready: BTreeSet<_> = remaining
2624	            .iter()
2625	            .filter_map(|(id, count)| (*count == 0).then_some(id.clone()))
2626	            .collect();
2627	        let mut ordered = Vec::with_capacity(prerequisites.len());
2628	        while let Some(id) = ready.pop_first() {
2629	            ordered.push(id.clone());
2630	            for dependent in dependents.get(&id).into_iter().flatten() {
2631	                let count = remaining.get_mut(dependent).expect("known successor node");
2632	                *count -= 1;
2633	                if *count == 0 {
2634	                    ready.insert(dependent.clone());
2635	                }
2636	            }
2637	        }
2638	        (ordered.len() == prerequisites.len())
2639	            .then_some(ordered)
2640	            .ok_or(SuccessorError::CyclicPrerequisites)
2641	    }
