2643	    fn digest_intent(
2644	        release: &ProductReleaseId,
2645	        source: &CommitSha,
2646	        operations: &[ReleaseOperation],
2647	        slots: &[ReleaseArtifactSlot],
2648	    ) -> IntentDigest {
2649	        let mut transcript = CanonicalTranscript::intent_v1();
2650	        transcript.push_str("successor.schema", "1");
2651	        transcript.push_str("product", release.product.as_str());
2652	        transcript.push_str("product.version", release.version.render());
2653	        transcript.push_str("source", source.as_str());
2654	        for operation in operations {
2655	            transcript.push_bytes(
2656	                "operation",
2657	                serde_json::to_vec(&operation.id).expect("closed operation serializes"),
2658	            );
2659	            for prerequisite in &operation.prerequisites {
2660	                transcript.push_bytes(
2661	                    "prerequisite",
2662	                    serde_json::to_vec(prerequisite).expect("closed operation serializes"),
2663	                );
2664	            }
2665	        }
2666	        for slot in slots {
2667	            transcript.push_bytes("slot", serde_json::to_vec(slot).expect("closed slot serializes"));
2668	        }
2669	        IntentDigest::from_transcript(&transcript)
2670	    }
