2885	    fn checksum_roster(
2886	        intent: &ReleaseIntent,
2887	        manifest: &ReleaseArtifactManifest,
2888	        metadata_digest: ArtifactDigest,
2889	    ) -> Result<Vec<ChecksumRosterEntry>, SuccessorError> {
2890	        manifest.validate_for_intent(intent)?;
2891	        if manifest.entries.iter().any(|entry| {
2892	            matches!(entry.slot, ReleaseArtifactSlot::ReleaseMetadata { .. }) && entry.digest != metadata_digest
2893	        }) {
2894	            return Err(SuccessorError::InvalidChecksumRoster);
2895	        }
2896	        let mut entries = manifest
2897	            .entries
2898	            .iter()
2899	            .filter_map(|entry| match entry.slot {
2900	                ReleaseArtifactSlot::ProductAsset { .. } | ReleaseArtifactSlot::ReleaseMetadata { .. } => {
2901	                    Some(ChecksumRosterEntry {
2902	                        file_name: entry.slot.file_name().to_string(),
2903	                        digest: if matches!(entry.slot, ReleaseArtifactSlot::ReleaseMetadata { .. }) {
2904	                            metadata_digest.clone()
2905	                        } else {
2906	                            entry.digest.clone()
2907	                        },
2908	                    })
2909	                }
2910	                ReleaseArtifactSlot::RegistryPackage { .. } | ReleaseArtifactSlot::ChecksumManifest { .. } => None,
2911	            })
2912	            .collect::<Vec<_>>();
2913	        entries.sort_by(|left, right| left.file_name.cmp(&right.file_name));
2914	        if entries.len() != 5
2915	            || entries.iter().any(|entry| entry.file_name == CHECKSUM_FILE_NAME)
2916	            || entries.windows(2).any(|pair| pair[0].file_name == pair[1].file_name)
2917	        {
2918	            return Err(SuccessorError::InvalidChecksumRoster);
2919	        }
2920	        Ok(entries)
2921	    }
