3457	    /// The digest-validating `Deserialize` impl calls `new()` internally, so
3458	    /// a hand-crafted (but internally digest-consistent) decision claiming
3459	    /// divergent group targets must be rejected the same way a freshly
3460	    /// derived one is -- this is the path a merge-commit verifier reading a
3461	    /// committed decision file actually exercises, not just direct
3462	    /// `ReleaseDecisionV1::new()` calls from a version plan.
3463	    #[test]
3464	    fn decision_deserialization_rejects_divergent_group_targets_even_with_a_self_consistent_digest() {
3465	        let a = ReleasePackageId::parse("cargo/crate-a").unwrap();
3466	        let b = ReleasePackageId::parse("cargo/crate-b").unwrap();
3467	        let entries = vec![
3468	            ReleaseDecisionEntry {
3469	                package: a,
3470	                target_version: Version::semver(1, 1, 0),
3471	                reasons: vec![ReleaseInclusionReason::FixedGroup {
3472	                    group_id: "demo".to_string(),
3473	                }],
3474	            },
3475	            ReleaseDecisionEntry {
3476	                package: b,
3477	                target_version: Version::semver(1, 2, 0),
3478	                reasons: vec![ReleaseInclusionReason::FixedGroup {
3479	                    group_id: "demo".to_string(),
3480	                }],
3481	            },
3482	        ];
3483	        // Hand-compute a digest matching this exact (invalid) entry set, so
3484	        // the failure below is provably the group-divergence check and not
3485	        // just the pre-existing digest-mismatch guard.
3486	        let digest = decision_digest(&entries);
3487	        let wire = serde_json::json!({
3488	            "schemaVersion": ReleaseDecisionV1::SCHEMA_VERSION,
3489	            "entries": entries,
3490	            "digest": digest,
3491	        });
3492	        let result: Result<ReleaseDecisionV1, _> = serde_json::from_value(wire);
3493	        assert!(
3494	            result.is_err(),
3495	            "expected divergent group targets to be rejected on deserialize"
3496	        );
3497	    }
