3562	    /// Two `ArtifactUpload` operations that share package/version/platform/asset_name
3563	    /// but differ only in `attestation_policy` are distinct `ArtifactSlotId`s and must
3564	    /// remain distinct `ReleaseOperationId`s under `Ord`, not just `Eq` -- otherwise
3565	    /// `BTreeSet`/`BTreeMap` keys silently collapse them (the `a.cmp(b) == Equal implies
3566	    /// a == b` invariant those collections require).
3567	    #[test]
3568	    fn artifact_upload_ids_differing_only_by_attestation_policy_stay_distinct_under_ord() {
3569	        let package = ReleasePackageId::parse("cargo/demo").unwrap();
3570	        let version = Version::semver(1, 0, 0);
3571	        let slot_a = ArtifactSlotId::new(
3572	            package.clone(),
3573	            version.clone(),
3574	            "x86_64-unknown-linux-gnu",
3575	            "demo.tar.gz",
3576	            GitHubRepository::parse("orin-dx/callisto").unwrap(),
3577	            ".github/workflows/release.yml",
3578	            CommitSha::parse(&"a".repeat(40)).unwrap(),
3579	        )
3580	        .unwrap();
3581	        let slot_b = ArtifactSlotId::new(
3582	            package,
3583	            version,
3584	            "x86_64-unknown-linux-gnu",
3585	            "demo.tar.gz",
3586	            GitHubRepository::parse("orin-dx/callisto").unwrap(),
3587	            ".github/workflows/release.yml",
3588	            CommitSha::parse(&"b".repeat(40)).unwrap(),
3589	        )
3590	        .unwrap();
3591	        assert_ne!(slot_a, slot_b, "the two slots must differ only by attestation_policy");
3592	
3593	        let id_a = ReleaseOperationId::artifact_upload(slot_a.clone());
3594	        let id_b = ReleaseOperationId::artifact_upload(slot_b.clone());
3595	
3596	        assert_ne!(id_a, id_b, "distinct attestation policies must stay Eq-distinct");
3597	        assert_ne!(
3598	            id_a.cmp(&id_b),
3599	            Ordering::Equal,
3600	            "distinct attestation policies must not compare Ord::Equal"
3601	        );
3602	
3603	        let mut ids = BTreeSet::new();
3604	        assert!(ids.insert(id_a.clone()), "first id must insert");
3605	        assert!(
3606	            ids.insert(id_b.clone()),
3607	            "second id must NOT be displaced by the first in a BTreeSet"
