3614	        let op_b = ReleaseOperation::artifact_upload(slot_b.clone(), vec![]).unwrap();
3615	        let (first, second) = if op_a.id() <= op_b.id() {
3616	            (op_a, op_b)
3617	        } else {
3618	            (op_b, op_a)
3619	        };
3620	        let (first_slot, second_slot) = if first.id() == &id_a {
3621	            (slot_a, slot_b)
3622	        } else {
3623	            (slot_b, slot_a)
3624	        };
3625	        let intent = test_intent_with_slots(
