3637	    /// Residual instance of the same defect class fixed above for
3638	    /// `attestation_policy`: `ReleaseOperationId::cmp` used to key on
3639	    /// `version.render()` alone, dropping `version.grammar()`. The same
3640	    /// literal string parses under more than one grammar -- `"1.2.3"` is
3641	    /// valid both as SemVer and PEP 440 -- so two `ReleaseOperationId`s
3642	    /// that are Eq-distinct only by `Version::grammar` collapsed to
3643	    /// `Ordering::Equal` under the old `render()`-only `Ord`, violating
3644	    /// the invariant `BTreeSet`/`BTreeMap` require: `a.cmp(b) == Equal`
3645	    /// iff `a == b`.
3646	    #[test]
3647	    fn operation_ids_differing_only_by_version_grammar_stay_distinct_under_ord() {
3648	        let package = ReleasePackageId::parse("cargo/demo").unwrap();
3649	        let v_semver = Version::parse("1.2.3", VersionGrammar::SemVer).unwrap();
3650	        let v_pep440 = Version::parse("1.2.3", VersionGrammar::Pep440).unwrap();
3651	
3652	        // Precondition: the identical literal renders identically under both
3653	        // grammars, but the parsed Versions are NOT the same value -- this is
3654	        // exactly the collision `version_ord_key` must resolve.
3655	        assert_eq!(v_semver.render(), v_pep440.render());
3656	        assert_ne!(
3657	            v_semver, v_pep440,
3658	            "SemVer and PEP 440 parses of the identical literal must remain Eq-distinct"
3659	        );
3660	
3661	        let id_a = ReleaseOperationId::tag(package.clone(), v_semver);
3662	        let id_b = ReleaseOperationId::tag(package, v_pep440);
3663	
3664	        assert_ne!(id_a, id_b, "distinct version grammars must stay Eq-distinct");
3665	        assert_ne!(
3666	            id_a.cmp(&id_b),
3667	            Ordering::Equal,
3668	            "distinct version grammars must not compare Ord::Equal"
3669	        );
3670	
3671	        let mut ids = BTreeSet::new();
3672	        assert!(ids.insert(id_a.clone()), "first id must insert");
3673	        assert!(
3674	            ids.insert(id_b.clone()),
3675	            "second id must NOT be displaced by the first in a BTreeSet"
3676	        );
3677	        assert_eq!(ids.len(), 2, "BTreeSet must not silently collapse distinct-grammar ids");
3678	
3679	        // Sanity check the ordinary case still behaves: several distinct
3680	        // plain SemVer versions of the same package/role must all survive
3681	        // as separate BTreeSet entries too, not just the grammar-collision
3682	        // edge case above.
3683	        let mut ordinary_ids = BTreeSet::new();
3684	        for raw in ["1.0.0", "1.2.3", "2.0.0", "0.9.9"] {
3685	            let id = ReleaseOperationId::tag(
3686	                ReleasePackageId::parse("cargo/demo").unwrap(),
3687	                Version::parse(raw, VersionGrammar::SemVer).unwrap(),
3688	            );
3689	            assert!(
3690	                ordinary_ids.insert(id),
3691	                "version {raw} must not collide with a prior entry"
3692	            );
3693	        }
3694	        assert_eq!(ordinary_ids.len(), 4);
3695	    }
