  35	/// An exact, ecosystem-qualified package identity for durable release operations.
  36	///
  37	/// Unlike PackageId, this type has no bare form and therefore cannot use
  38	/// wildcard matching across ecosystems.
  39	#[derive(Clone, Debug, PartialEq, Eq, Hash, JsonSchema)]
  40	#[schemars(with = "String")]
  41	pub struct ReleasePackageId {
  42	    ecosystem: Ecosystem,
  43	    name: String,
  44	}
  45	
  46	impl ReleasePackageId {
  47	    /// Creates an exact release package identity.
  48	    ///
  49	    /// # Errors
  50	    ///
  51	    /// Returns ReleasePackageIdParseError when name is not valid in the
  52	    /// existing package-identity grammar.
  53	    pub fn new(ecosystem: Ecosystem, name: impl AsRef<str>) -> Result<Self, ReleasePackageIdParseError> {
  54	        let name = name.as_ref();
  55	        let raw = format!("{}/{}", ecosystem.prefix(), name);
  56	        match PackageId::parse(&raw) {
  57	            Ok(PackageId::Prefixed {
  58	                ecosystem: parsed_ecosystem,
  59	                name: parsed_name,
  60	            }) if parsed_ecosystem == ecosystem && parsed_name == name => Ok(Self {
  61	                ecosystem,
  62	                name: parsed_name,
  63	            }),
  64	            _ => Err(ReleasePackageIdParseError::Malformed { raw }),
  65	        }
  66	    }
  67	
  68	    /// Parses the canonical 'ecosystem/name' release identity form.
  69	    ///
  70	    /// PackageId also accepts 'ecosystem:name'; release identities reject it
  71	    /// so every durable encoding has exactly one spelling.
  72	    pub fn parse(s: &str) -> Result<Self, ReleasePackageIdParseError> {
  73	        if s.contains(':') {
  74	            return Err(ReleasePackageIdParseError::NonCanonical { raw: s.to_string() });
  75	        }
  76	        let (prefix, name) = s
  77	            .split_once('/')
  78	            .ok_or_else(|| ReleasePackageIdParseError::MissingEcosystem { raw: s.to_string() })?;
  79	        let ecosystem = Ecosystem::from_prefix(prefix)
  80	            .ok_or_else(|| ReleasePackageIdParseError::UnknownEcosystem { raw: s.to_string() })?;
  81	        let id = Self::new(ecosystem, name)?;
  82	        if id.to_string() != s {
  83	            return Err(ReleasePackageIdParseError::NonCanonical { raw: s.to_string() });
  84	        }
  85	        Ok(id)
  86	    }
