 158	/// An exact `owner/repo` GitHub repository identity.
 159	///
 160	/// Replaces three previously independent, inconsistent ad hoc validations of
 161	/// the same concept (a bare `split_once('/')` check with no character-class
 162	/// restriction, a stricter ASCII-alphanumeric-plus-`-_.` check, and an
 163	/// entirely unvalidated `format!("{owner}/{repository}")`); every caller now
 164	/// parses through this single charset rule instead.
 165	#[derive(Clone, Debug, PartialEq, Eq, Hash, JsonSchema)]
 166	#[schemars(with = "String")]
 167	pub struct GitHubRepository {
 168	    owner: String,
 169	    repo: String,
 170	}
 171	
 172	impl GitHubRepository {
 173	    /// Parses an exact `owner/repo` GitHub repository identity.
 174	    ///
 175	    /// Both `owner` and `repo` must be non-empty, ASCII alphanumeric plus
 176	    /// `-`, `_`, and `.`, and must not start or end with `-`. This is
 177	    /// deliberately one charset rule applied uniformly to both parts,
 178	    /// matching GitHub's own allowed repository-name charset closely enough
 179	    /// to reject the unsafe inputs that matter (for example, embedded
 180	    /// whitespace) without re-implementing GitHub's full, occasionally
 181	    /// stricter, username rules.
 182	    pub fn parse(s: &str) -> Result<Self, GitHubRepositoryParseError> {
 183	        let Some((owner, repo)) = s.split_once('/') else {
 184	            return Err(GitHubRepositoryParseError::MissingSeparator { raw: s.to_string() });
 185	        };
 186	        if repo.contains('/') {
 187	            return Err(GitHubRepositoryParseError::TooManyParts { raw: s.to_string() });
 188	        }
 189	        if !is_valid_github_repository_part(owner) {
 190	            return Err(GitHubRepositoryParseError::InvalidOwner { raw: s.to_string() });
 191	        }
 192	        if !is_valid_github_repository_part(repo) {
 193	            return Err(GitHubRepositoryParseError::InvalidRepo { raw: s.to_string() });
 194	        }
 195	        Ok(Self {
 196	            owner: owner.to_string(),
 197	            repo: repo.to_string(),
 198	        })
 199	    }
 200	
 201	    /// Returns the owner component.
 202	    pub fn owner(&self) -> &str {
 203	        &self.owner
 204	    }
