 285	macro_rules! release_digest {
 286	    ($name:ident, $description:literal) => {
 287	        #[doc = $description]
 288	        #[derive(Clone, Debug, PartialEq, Eq, Hash, PartialOrd, Ord, JsonSchema)]
 289	        #[schemars(with = "String")]
 290	        pub struct $name(String);
 291	
 292	        impl $name {
 293	            /// Parses a lowercase hexadecimal SHA-256 digest.
 294	            pub fn parse(raw: &str) -> Result<Self, DigestParseError> {
 295	                if raw.len() != 64
 296	                    || !raw
 297	                        .bytes()
 298	                        .all(|byte| byte.is_ascii_digit() || (b'a'..=b'f').contains(&byte))
 299	                {
 300	                    return Err(DigestParseError {
 301	                        digest_kind: stringify!($name),
 302	                        raw: raw.to_string(),
 303	                    });
 304	                }
 305	                Ok(Self(raw.to_string()))
 306	            }
 307	
 308	            /// Returns the canonical lowercase hexadecimal digest.
 309	            pub fn as_str(&self) -> &str {
 310	                &self.0
 311	            }
 312	
 313	            fn from_sha256(bytes: impl AsRef<[u8]>) -> Self {
 314	                let rendered = format!("{:x}", Sha256::digest(bytes.as_ref()));
 315	                Self(rendered)
 316	            }
 317	        }
 318	
 319	        impl fmt::Display for $name {
 320	            fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
 321	                f.write_str(&self.0)
 322	            }
 323	        }
 324	
 325	        impl Serialize for $name {
 326	            fn serialize<S>(&self, serializer: S) -> Result<S::Ok, S::Error>
 327	            where
 328	                S: Serializer,
 329	            {
 330	                serializer.serialize_str(&self.0)
 331	            }
 332	        }
 333	
 334	        impl<'de> Deserialize<'de> for $name {
 335	            fn deserialize<D>(deserializer: D) -> Result<Self, D::Error>
 336	            where
 337	                D: Deserializer<'de>,
 338	            {
 339	                let raw = String::deserialize(deserializer)?;
 340	                Self::parse(&raw).map_err(serde::de::Error::custom)
 341	            }
 342	        }
 343	    };
 344	}
