 363	impl ArtifactDigest {
 364	    /// Hashes the exact artifact bytes without normalization.
 365	    pub fn from_bytes(bytes: impl AsRef<[u8]>) -> Self {
 366	        Self::from_sha256(bytes)
 367	    }
 368	
 369	    /// Streams exact artifact bytes into SHA-256 without retaining the full
 370	    /// asset in memory. Release artifacts can be substantially larger than
 371	    /// manifests, so executor verification must use this path.
 372	    pub fn from_reader(mut reader: impl Read) -> std::io::Result<(Self, u64)> {
 373	        let mut hasher = Sha256::new();
 374	        let mut length = 0_u64;
 375	        let mut buffer = [0_u8; 64 * 1024];
 376	        loop {
 377	            let read = reader.read(&mut buffer)?;
 378	            if read == 0 {
 379	                break;
 380	            }
 381	            hasher.update(&buffer[..read]);
 382	            length = length.checked_add(read as u64).ok_or_else(|| {
 383	                std::io::Error::new(std::io::ErrorKind::InvalidData, "artifact exceeds supported length")
 384	            })?;
 385	        }
 386	        Ok((Self(format!("{:x}", hasher.finalize())), length))
 387	    }
 388	}
