1406	fn digest_intent(
1407	    decision: &ReleaseDecisionV1,
1408	    snapshot: &ReleaseInputSnapshotV1,
1409	    trust_profile: ExecutionTrustProfileV1,
1410	    operations: &[ReleaseOperation],
1411	    artifact_slots: &[ArtifactSlotId],
1412	) -> IntentDigest {
1413	    let mut transcript = CanonicalTranscript::intent_v1();
1414	    transcript.push_bytes("schema", [ReleaseIntentV1::SCHEMA_VERSION]);
1415	    transcript.push_str("decision", decision.digest.as_str());
1416	    transcript.push_str("snapshot", snapshot.digest().as_str());
1417	    transcript.push_str(
1418	        "trust-profile",
1419	        match trust_profile {
1420	            ExecutionTrustProfileV1::GitCommit => "git-commit",
1421	            ExecutionTrustProfileV1::HermeticContent => "hermetic-content",
1422	        },
1423	    );
1424	    for operation in operations {
1425	        transcript.push_str("operation", &operation_id_text(&operation.id));
1426	        for prerequisite in &operation.prerequisites {
1427	            transcript.push_str("prerequisite", &operation_id_text(prerequisite));
1428	        }
1429	    }
1430	    for slot in artifact_slots {
1431	        transcript.push_str("artifact-slot.package", &slot.package.to_string());
1432	        transcript.push_str("artifact-slot.version", slot.version.render());
1433	        transcript.push_str("artifact-slot.platform", &slot.platform);
1434	        transcript.push_str("artifact-slot.asset", &slot.asset_name);
1435	        transcript.push_str(
1436	            "artifact-slot.repository",
