1503	fn validate_operations(operations: &[ReleaseOperation]) -> Result<(), ReleaseIntentError> {
1504	    let mut ids = BTreeSet::new();
1505	    for operation in operations {
1506	        if !ids.insert(operation.id.clone()) {
1507	            return Err(ReleaseIntentError::DuplicateOperation {
1508	                id: Box::new(operation.id.clone()),
1509	            });
1510	        }
1511	    }
1512	    for operation in operations {
1513	        if operation.prerequisites.windows(2).any(|pair| pair[0] >= pair[1]) {
1514	            return Err(ReleaseIntentError::NonCanonicalPrerequisiteOrder {
1515	                id: Box::new(operation.id.clone()),
1516	            });
1517	        }
1518	        for prerequisite in &operation.prerequisites {
1519	            if prerequisite == &operation.id {
1520	                return Err(ReleaseIntentError::SelfPrerequisite {
1521	                    id: Box::new(operation.id.clone()),
1522	                });
1523	            }
1524	            if !ids.contains(prerequisite) {
1525	                return Err(ReleaseIntentError::UnknownPrerequisite {
1526	                    id: Box::new(operation.id.clone()),
1527	                    prerequisite: Box::new(prerequisite.clone()),
1528	                });
1529	            }
1530	        }
1531	    }
1532	    let edges: BTreeMap<_, _> = operations
1533	        .iter()
1534	        .map(|operation| (operation.id.clone(), operation.prerequisites.clone()))
1535	        .collect();
1536	    let canonical = stable_kahn_order(&edges)?;
1537	    if operations.iter().map(ReleaseOperation::id).ne(canonical.iter()) {
1538	        return Err(ReleaseIntentError::NonCanonicalOperationOrder);
1539	    }
1540	    Ok(())
1541	}
