1543	fn stable_kahn_order(
1544	    prerequisites: &BTreeMap<ReleaseOperationId, Vec<ReleaseOperationId>>,
1545	) -> Result<Vec<ReleaseOperationId>, ReleaseIntentError> {
1546	    let mut remaining: BTreeMap<_, usize> = prerequisites
1547	        .iter()
1548	        .map(|(id, prerequisites)| (id.clone(), prerequisites.len()))
1549	        .collect();
1550	    let mut dependents = BTreeMap::<ReleaseOperationId, Vec<ReleaseOperationId>>::new();
1551	    for (id, prerequisites) in prerequisites {
1552	        for prerequisite in prerequisites {
1553	            dependents.entry(prerequisite.clone()).or_default().push(id.clone());
1554	        }
1555	    }
1556	    let mut ready: BTreeSet<_> = remaining
1557	        .iter()
1558	        .filter_map(|(id, count)| (*count == 0).then_some(id.clone()))
1559	        .collect();
1560	    let mut ordered = Vec::with_capacity(prerequisites.len());
1561	    while let Some(id) = ready.pop_first() {
1562	        ordered.push(id.clone());
1563	        for dependent in dependents.get(&id).into_iter().flatten() {
1564	            let count = remaining.get_mut(dependent).expect("known DAG node");
1565	            *count -= 1;
1566	            if *count == 0 {
1567	                ready.insert(dependent.clone());
1568	            }
1569	        }
1570	    }
1571	    if ordered.len() != prerequisites.len() {
1572	        let id = remaining
1573	            .into_iter()
1574	            .find_map(|(id, count)| (count != 0).then_some(id))
1575	            .expect("a nonempty cyclic DAG has a remaining node");
1576	        return Err(ReleaseIntentError::Cycle { id: Box::new(id) });
1577	    }
1578	    Ok(ordered)
1579	}
