#[derive(Clone, Debug, PartialEq, Eq, Serialize, JsonSchema)]
#[serde(rename_all = "camelCase", deny_unknown_fields)]
pub(super) struct ReleaseIntent {
    schema_version: u8,
    product_release: ProductReleaseId,
    source_commit: CommitSha,
    registry_packages: Vec<ApprovedRegistryPackage>,
    operations: Vec<ReleaseOperation>,
    slots: Vec<ReleaseArtifactSlot>,
    digest: IntentDigest,
}

#[derive(Deserialize)]
#[serde(rename_all = "camelCase", deny_unknown_fields)]
struct ReleaseIntentWire {
    schema_version: u8,
    product_release: ProductReleaseId,
    source_commit: CommitSha,
    registry_packages: Vec<ApprovedRegistryPackage>,
    operations: Vec<ReleaseOperation>,
    slots: Vec<ReleaseArtifactSlot>,
    digest: IntentDigest,
}

impl ReleaseIntent {
    const SCHEMA_VERSION: u8 = 1;

    fn new(
        product_release: ProductReleaseId,
        source_commit: CommitSha,
        mut registry_packages: Vec<ApprovedRegistryPackage>,
        operations: Vec<ReleaseOperation>,
        mut slots: Vec<ReleaseArtifactSlot>,
    ) -> Result<Self, SuccessorError> {
        slots.sort();
        registry_packages.sort();
        if registry_packages.windows(2).any(|pair| pair[0] == pair[1]) {
            return Err(SuccessorError::DuplicateRegistryPackage);
        }
        validate_slot_roster(&product_release, &registry_packages, &slots)?;
        validate_operations(&product_release, &registry_packages, &operations, &slots)?;
        let digest = digest_intent(
            &product_release,
            &source_commit,
            &registry_packages,
            &operations,
            &slots,
        );
        Ok(Self {
            schema_version: Self::SCHEMA_VERSION,
            product_release,
            source_commit,
            registry_packages,
            operations,
            slots,
            digest,
        })
    }
}

impl<'de> Deserialize<'de> for ReleaseIntent {
    fn deserialize<D>(deserializer: D) -> Result<Self, D::Error>
    where
        D: Deserializer<'de>,
    {
        let wire = ReleaseIntentWire::deserialize(deserializer)?;
        if wire.schema_version != Self::SCHEMA_VERSION {
            return Err(serde::de::Error::custom("unsupported successor release intent schema"));
        }
        let intent = Self::new(
            wire.product_release,
            wire.source_commit,
            wire.registry_packages,
            wire.operations,
            wire.slots,
        )
        .map_err(serde::de::Error::custom)?;
        (intent.digest == wire.digest)
            .then_some(intent)
            .ok_or_else(|| serde::de::Error::custom("successor release intent digest is not canonical"))
    }
}

fn validate_slot_roster(
    release: &ProductReleaseId,
    approved: &[ApprovedRegistryPackage],
    slots: &[ReleaseArtifactSlot],
) -> Result<(), SuccessorError> {
    if slots.windows(2).any(|pair| pair[0] == pair[1]) {
        return Err(SuccessorError::DuplicateSlot);
    }
    for slot in slots {
        slot.validate(release)?;
    }
    let registry_slots = slots
        .iter()
        .filter(|slot| match slot {
            ReleaseArtifactSlot::RegistryPackage {
                package,
                version,
                registry,
                format,
                ..
            } => {
                version == &release.version
                    && approved.iter().any(|expected| {
                        expected.package == *package && expected.registry == *registry && expected.format == *format
                    })
            }
            _ => false,
        })
        .count();
    if registry_slots != approved.len() {
        return Err(SuccessorError::RegistrySlotOutsideApprovedRoster);
