#[derive(Deserialize)]
#[serde(rename_all = "camelCase", deny_unknown_fields)]
struct ReleaseDistributionMetadataV1Wire {
    schema_version: u8,
    product_release: ProductReleaseId,
    intent_digest: IntentDigest,
    source_commit: CommitSha,
    payloads: Vec<MetadataPayload>,
    verification_policy: ProvenancePolicy,
}

impl ReleaseDistributionMetadataV1 {
    const SCHEMA_VERSION: u8 = 1;

    fn from_payloads(intent: &ReleaseIntent, validated: &ValidatedPayloadEntries) -> Result<Self, SuccessorError> {
        let mut payloads = validated
            .entries
            .iter()
            .filter_map(|entry| match &entry.slot {
                ReleaseArtifactSlot::ProductAsset {
                    target,
                    file_name,
                    provenance_policy,
                    ..
                } => Some(MetadataPayload {
                    target: *target,
                    file_name: file_name.clone(),
                    digest: entry.digest.clone(),
                    byte_length: entry.byte_length,
                    provenance_policy: provenance_policy.clone(),
                }),
                _ => None,
            })
            .collect::<Vec<_>>();
        payloads.sort_by_key(|payload| payload.target);
        let verification_policy = payloads
            .first()
            .expect("closed product roster contains product payloads")
            .provenance_policy
            .clone();
        let metadata = Self {
            schema_version: Self::SCHEMA_VERSION,
            product_release: intent.product_release.clone(),
            intent_digest: intent.digest.clone(),
            source_commit: intent.source_commit.clone(),
            payloads,
            verification_policy,
        };
        metadata.validate()?;
        Ok(metadata)
    }

    fn canonical_json(&self) -> Vec<u8> {
        serde_json::to_vec(self).expect("closed metadata serializes")
    }

    fn validate(&self) -> Result<(), SuccessorError> {
        if self.schema_version != Self::SCHEMA_VERSION
            || self.payloads.len() != ProductTarget::ALL.len()
            || self.payloads.windows(2).any(|pair| pair[0].target >= pair[1].target)
            || !ProductTarget::ALL.iter().zip(&self.payloads).all(|(target, payload)| {
                target == &payload.target && is_safe_artifact_component(&payload.file_name)
            })
            || self
                .payloads
                .iter()
                .any(|payload| payload.provenance_policy.validate().is_err())
            || self.verification_policy.validate().is_err()
            || self
                .payloads
                .iter()
                .any(|payload| payload.provenance_policy != self.verification_policy)
        {
            return Err(SuccessorError::InvalidMetadata);
        }
        Ok(())
    }
}

impl<'de> Deserialize<'de> for ReleaseDistributionMetadataV1 {
    fn deserialize<D>(deserializer: D) -> Result<Self, D::Error>
    where
        D: Deserializer<'de>,
    {
        let wire = ReleaseDistributionMetadataV1Wire::deserialize(deserializer)?;
        let metadata = Self {
            schema_version: wire.schema_version,
            product_release: wire.product_release,
            intent_digest: wire.intent_digest,
            source_commit: wire.source_commit,
            payloads: wire.payloads,
            verification_policy: wire.verification_policy,
        };
        metadata.validate().map(|()| metadata).map_err(serde::de::Error::custom)
    }
}

#[derive(Clone, Debug, PartialEq, Eq)]
pub(super) struct ChecksumRosterEntry {
    file_name: String,
    digest: ArtifactDigest,
}

impl ChecksumRosterEntry {
    fn line(&self) -> String {
        format!("{}  {}\n", self.digest, self.file_name)
    }
}

fn canonical_checksum_bytes(
    payload_entries: &[ReleaseArtifactEntry],
    metadata_entry: &ReleaseArtifactEntry,
) -> Result<Vec<u8>, SuccessorError> {
    let mut entries = payload_entries
        .iter()
        .filter_map(|entry| match entry.slot {
            ReleaseArtifactSlot::ProductAsset { .. } => Some(ChecksumRosterEntry {
                file_name: entry.slot.file_name().to_string(),
                digest: entry.digest.clone(),
            }),
            ReleaseArtifactSlot::RegistryPackage { .. }
            | ReleaseArtifactSlot::ChecksumManifest { .. }
            | ReleaseArtifactSlot::ReleaseMetadata { .. } => None,
        })
        .collect::<Vec<_>>();
    entries.push(ChecksumRosterEntry {
        file_name: metadata_entry.slot.file_name().to_string(),
        digest: metadata_entry.digest.clone(),
    });
    entries.sort_by(|left, right| left.file_name.cmp(&right.file_name));
    if entries.len() != 5
        || entries.iter().any(|entry| entry.file_name == CHECKSUM_FILE_NAME)
        || entries.windows(2).any(|pair| pair[0].file_name == pair[1].file_name)
    {
        return Err(SuccessorError::InvalidChecksumRoster);
    }
    Ok(entries
        .into_iter()
        .flat_map(|entry| entry.line().into_bytes())
        .collect())
}

#[derive(Clone, Debug, PartialEq, Eq, thiserror::Error)]
enum SuccessorError {
    #[error("product name `{raw}` is not canonical and safe")]
    InvalidProductName { raw: String },
    #[error("coordinated release version `{version}` is not SemVer")]
    NonSemverProductVersion { version: Box<Version> },
    #[error("coordinated release has no package versions")]
    EmptyCoordinatedRoster,
    #[error("coordinated release versions diverge: expected {expected}, found {found}")]
    DivergentCoordinatedVersion {
        expected: Box<Version>,
        found: Box<Version>,
    },
    #[error("artifact slot is unsafe")]
    UnsafeArtifactSlot,
    #[error("artifact slot provenance is invalid")]
    InvalidProvenance,
    #[error("reserved artifact file name is wrong")]
    WrongReservedFileName,
    #[error("artifact slot refers to a different product release")]
    ForeignProductRelease,
    #[error("package operation does not own its registry slot")]
    InvalidPackageOperation,
    #[error("registry artifact format does not match package ecosystem")]
    RegistryFormatMismatch,
    #[error("approved registry package roster contains a duplicate")]
    DuplicateRegistryPackage,
    #[error("registry slot is not in the approved coordinated roster")]
    RegistrySlotOutsideApprovedRoster,
    #[error("forge operations and product provenance must address one repository")]
    MismatchedForgeRepository,
    #[error("product operation does not own the coordinated product release")]
    InvalidProductOperation,
    #[error("release operation prerequisites are invalid")]
    InvalidPrerequisite,
    #[error("release operation identities are duplicated")]
    DuplicateOperation,
    #[error("artifact slots are duplicated")]
    DuplicateSlot,
    #[error("artifact file names are duplicated")]
    DuplicateFileName,
    #[error("product artifact roster is not the closed supported set")]
    InvalidProductRoster,
    #[error("release operations are not in canonical topological order")]
    NonCanonicalOperationOrder,
    #[error("release operation prerequisites contain a cycle")]
    CyclicPrerequisites,
    #[error("artifact manifest differs from the intent-bound roster")]
    MismatchedManifest,
    #[error("distribution metadata is not canonical")]
    InvalidMetadata,
    #[error("checksum roster is not the exact payload plus metadata set")]
    InvalidChecksumRoster,
}

