            let approved =
                ApprovedRegistryPackage::new(package.clone(), registry.clone(), RegistryArtifactFormat::CargoCrate)
                    .unwrap();
            let registry_slot = ReleaseArtifactSlot::RegistryPackage {
                package: package.clone(),
                version: release.version.clone(),
                registry: registry.clone(),
                format: RegistryArtifactFormat::CargoCrate,
                file_name: "callisto-model-1.2.3.crate".to_string(),
                provenance_policy: policy(),
            };
            let mut all_slots = slots(&release);
            all_slots.push(registry_slot.clone());
            let publish_registry = ReleaseOperationId::RegistryArtifactPublish {
                package,
                version: release.version.clone(),
                registry,
                slot: registry_slot,
            };
            let tag = ReleaseOperationId::ProductTag {
                release: release.clone(),
                tag: release.tag(),
            };
            let prepare = ReleaseOperationId::ForgePrepare {
                release: release.clone(),
                repository: GitHubRepository::parse("callisto-rs/callisto").unwrap(),
            };
            let mut operations = vec![
                ReleaseOperation::new(publish_registry.clone(), vec![]).unwrap(),
                ReleaseOperation::new(tag.clone(), vec![publish_registry]).unwrap(),
                ReleaseOperation::new(prepare.clone(), vec![tag]).unwrap(),
            ];
            for slot in &all_slots {
                if slot.release().is_some() {
                    operations.push(
                        ReleaseOperation::new(
                            ReleaseOperationId::ArtifactUpload {
                                release: release.clone(),
                                slot: slot.clone(),
                            },
                            vec![prepare.clone()],
                        )
                        .unwrap(),
                    );
                }
            }
            let mut upload_ids = operations
                .iter()
                .filter_map(|operation| {
                    matches!(operation.id, ReleaseOperationId::ArtifactUpload { .. }).then_some(operation.id.clone())
                })
                .collect::<Vec<_>>();
            upload_ids.sort();
            let forge_publish = ReleaseOperationId::ForgePublish {
                release: release.clone(),
                repository: GitHubRepository::parse("callisto-rs/callisto").unwrap(),
            };
            operations.push(ReleaseOperation::new(forge_publish, upload_ids).unwrap());
            let edges: BTreeMap<_, _> = operations
                .iter()
                .map(|operation| (operation.id.clone(), operation.prerequisites.clone()))
                .collect();
            let order = stable_order(&edges).unwrap();
            let by_id: BTreeMap<_, _> = operations
                .into_iter()
                .map(|operation| (operation.id.clone(), operation))
                .collect();
            let intent = ReleaseIntent::new(
                release,
                commit(),
                vec![approved],
                order.into_iter().map(|id| by_id[&id].clone()).collect(),
                all_slots,
            )
            .unwrap();
            assert_eq!(intent.registry_packages.len(), 1);
            assert!(ApprovedRegistryPackage::new(
                ReleasePackageId::parse("cargo/wrong").unwrap(),
                registry_binding(),
                RegistryArtifactFormat::NpmTarball,
            )
            .is_err());
        }

        #[test]
        fn product_identity_is_safe_semver_and_canonical() {
            assert!(ProductName::parse("Callisto").is_err());
            assert!(ProductName::parse("callisto/").is_err());
            assert_eq!(release().tag(), "callisto@1.2.3");
            assert!(ProductReleaseId::from_coordinated_versions(
                ProductName::parse("callisto").unwrap(),
                [Version::semver(1, 2, 3), Version::semver(1, 2, 4)],
            )
            .is_err());
            assert!(ProductReleaseId::new(
                ProductName::parse("callisto").unwrap(),
                Version::parse("1.2.3", VersionGrammar::Pep440).unwrap(),
            )
            .is_err());
            let wire = serde_json::to_value(release()).unwrap();
            assert!(serde_json::from_value::<ProductReleaseId>(wire).is_ok());
            assert_eq!(
                serde_json::to_string(&ProductTarget::X86_64UnknownLinuxMusl).unwrap(),
                "\"x86_64-unknown-linux-musl\""
            );
        }

        #[test]
        fn closed_roster_operations_and_wire_are_strict() {
            let intent = intent();
            assert_eq!(intent.slots.len(), 6);
            let mut wire = serde_json::to_value(&intent).unwrap();
            wire["unexpected"] = serde_json::Value::Bool(true);
            assert!(serde_json::from_value::<ReleaseIntent>(wire).is_err());
            let mut missing = intent.slots.clone();
            missing.pop();
            assert!(ReleaseIntent::new(
                intent.product_release.clone(),
                commit(),
                intent.registry_packages.clone(),
                intent.operations.clone(),
                missing
            )
            .is_err());
            let mut duplicate = intent.slots.clone();
            duplicate.push(duplicate[0].clone());
            assert!(ReleaseIntent::new(
                intent.product_release.clone(),
                commit(),
                intent.registry_packages.clone(),
                intent.operations.clone(),
                duplicate
            )
            .is_err());
            let mut wrong_target = intent.slots.clone();
            if let ReleaseArtifactSlot::ProductAsset { target, .. } = wrong_target
                .iter_mut()
                .find(|slot| matches!(slot, ReleaseArtifactSlot::ProductAsset { .. }))
                .unwrap()
            {
                *target = ProductTarget::Wasm32Wasip1;
            }
            assert!(ReleaseIntent::new(
                intent.product_release.clone(),
                commit(),
                intent.registry_packages.clone(),
                intent.operations.clone(),
                wrong_target
            )
            .is_err());
            let mut unsafe_slot = intent.slots.clone();
            if let ReleaseArtifactSlot::ProductAsset { file_name, .. } = unsafe_slot
                .iter_mut()
                .find(|slot| matches!(slot, ReleaseArtifactSlot::ProductAsset { .. }))
                .unwrap()
            {
                *file_name = "../callisto.tar.gz".to_string();
            }
            assert!(ReleaseIntent::new(
                intent.product_release.clone(),
                commit(),
                intent.registry_packages.clone(),
                intent.operations.clone(),
                unsafe_slot
            )
            .is_err());
            let mut fifth_target = intent.slots.clone();
            fifth_target.push(ReleaseArtifactSlot::ProductAsset {
                release: intent.product_release.clone(),
                target: ProductTarget::Aarch64AppleDarwin,
                file_name: "callisto-extra.tar.gz".to_string(),
                provenance_policy: policy(),
            });
            assert!(ReleaseIntent::new(
                intent.product_release.clone(),
                commit(),
                intent.registry_packages.clone(),
                intent.operations.clone(),
                fifth_target
            )
            .is_err());
            let mut malformed_policy = serde_json::to_value(&intent).unwrap();
            let slot = malformed_policy["slots"]
                .as_array_mut()
                .unwrap()
                .iter_mut()
                .find(|slot| slot["kind"] == "productAsset")
                .unwrap();
            slot["provenancePolicy"]["githubAttestationRequired"] = serde_json::Value::Bool(false);
            assert!(serde_json::from_value::<ReleaseIntent>(malformed_policy).is_err());
            let mut wrong_forge = intent.operations.clone();
            if let ReleaseOperationId::ForgePublish { repository, .. } = &mut wrong_forge
                .iter_mut()
                .find(|operation| matches!(operation.id, ReleaseOperationId::ForgePublish { .. }))
                .unwrap()
                .id
            {
                *repository = GitHubRepository::parse("callisto-rs/other").unwrap();
            }
            assert!(ReleaseIntent::new(
                intent.product_release.clone(),
                commit(),
                intent.registry_packages.clone(),
                wrong_forge,
                intent.slots.clone()
            )
            .is_err());
        }

        #[test]
        fn manifest_metadata_and_checksum_are_bound_without_circularity() {
            let intent = intent();
            let entries = intent
                .slots
                .iter()
                .filter(|slot| {
                    matches!(
                        slot,
                        ReleaseArtifactSlot::RegistryPackage { .. } | ReleaseArtifactSlot::ProductAsset { .. }
                    )
                })
                .cloned()
                .map(|slot| ReleaseArtifactEntry {
                    digest: ArtifactDigest::from_bytes(slot.file_name().as_bytes()),
                    byte_length: slot.file_name().len() as u64,
                    source_commit: commit(),
                    provenance: slot.policy().clone(),
                    slot,
                })
                .collect::<Vec<_>>();
            let payloads = ValidatedPayloadEntries::new(&intent, entries).unwrap();
            let metadata = ReleaseDistributionMetadataV1::from_payloads(&intent, &payloads).unwrap();
            let manifest = ReleaseArtifactManifest::complete(&intent, &payloads).unwrap();
            assert_eq!(manifest.entries.len(), 6);
            assert!(manifest.validate_for_intent(&intent).is_ok());
            assert_eq!(
                serde_json::from_value::<ReleaseArtifactManifest>(serde_json::to_value(&manifest).unwrap()).unwrap(),
                manifest
            );
            assert_eq!(
                serde_json::from_value::<ReleaseDistributionMetadataV1>(serde_json::to_value(&metadata).unwrap())
                    .unwrap(),
                metadata
            );
            let mut forged = manifest.clone();
            forged.entries[0].source_commit = CommitSha::parse(&"b".repeat(40)).unwrap();
            assert!(forged.validate_for_intent(&intent).is_err());
            let mut forged_metadata = manifest.clone();
            forged_metadata
                .entries
                .iter_mut()
                .find(|entry| matches!(entry.slot, ReleaseArtifactSlot::ReleaseMetadata { .. }))
                .unwrap()
                .byte_length += 1;
            assert!(forged_metadata.validate_for_intent(&intent).is_err());
            let mut forged_checksum = manifest.clone();
            forged_checksum
                .entries
                .iter_mut()
                .find(|entry| matches!(entry.slot, ReleaseArtifactSlot::ChecksumManifest { .. }))
                .unwrap()
                .digest = ArtifactDigest::from_bytes("forged");
            assert!(forged_checksum.validate_for_intent(&intent).is_err());
            let mut metadata_wire = serde_json::to_value(metadata).unwrap();
            metadata_wire["unknown"] = serde_json::Value::Bool(true);
            assert!(serde_json::from_value::<ReleaseDistributionMetadataV1>(metadata_wire).is_err());
        }
    }
