}

impl ApprovedRegistryPackage {
    fn new(
        package: ReleasePackageId,
        registry: RegistryBindingId,
        format: RegistryArtifactFormat,
    ) -> Result<Self, SuccessorError> {
        if !format_matches_ecosystem(format.clone(), package.ecosystem()) {
            return Err(SuccessorError::RegistryFormatMismatch);
        }
        Ok(Self {
            package,
            registry,
            format,
        })
    }
}

impl<'de> Deserialize<'de> for ApprovedRegistryPackage {
    fn deserialize<D>(deserializer: D) -> Result<Self, D::Error>
    where
        D: Deserializer<'de>,
    {
        let wire = ApprovedRegistryPackageWire::deserialize(deserializer)?;
        Self::new(wire.package, wire.registry, wire.format).map_err(serde::de::Error::custom)
    }
}

fn format_matches_ecosystem(format: RegistryArtifactFormat, ecosystem: Ecosystem) -> bool {
    matches!(
        (format, ecosystem),
        (RegistryArtifactFormat::CargoCrate, Ecosystem::Cargo)
            | (RegistryArtifactFormat::NpmTarball, Ecosystem::Npm)
            | (
                RegistryArtifactFormat::PythonWheel | RegistryArtifactFormat::PythonSdist,
                Ecosystem::Pypi
            )
    )
}

